package ai.uldren.loom

private fun String?.keyBytes(): ByteArray? = this?.encodeToByteArray()

actual fun Loom.studioReindexJson(path: String, workspace: String, profile: String, passphrase: String?, kek: ByteArray?, authPrincipal: String?, authPassphrase: String?): String = LoomNative.nativeStudioReindexJson(path, workspace, profile, passphrase.keyBytes(), kek, authPrincipal, authPassphrase.keyBytes())
