actual fun Loom.auditCompact(path: String, throughSeq: Long, passphrase: String?, kek: ByteArray?, authPrincipal: String?, authPassphrase: String?): ByteArray {
    require(throughSeq >= 0) { "throughSeq must be non-negative" }
    return LoomNative.nativeAuditCompact(path, throughSeq, passphrase.keyBytes(), kek, authPrincipal, authPassphrase.keyBytes())
}
